// Convertit un e-mail Gmail (n8n) en charge utile `EmailIn` de l'API ACA.
//
// Les pièces jointes arrivent en binaire dans n8n ; l'API les attend en base64 (§16.1.1).
// C'est ce nœud qui rend l'analyse multimodale — le pilier d'innovation n°1 — accessible
// depuis n8n : avant, POST /threads ignorait purement et simplement les pièces jointes.
//
// `thread_id` est dérivé de l'identifiant Gmail : POST /threads est idempotent (§16.1.4),
// donc un réessai du nœud HTTP ne relance pas l'analyse et ne renotifie pas l'équipe.

const out = [];

for (const item of $input.all()) {
  const headers = item.json.headers || {};
  const attachments = [];

  for (const [key, meta] of Object.entries(item.binary || {})) {
    const buffer = await this.helpers.getBinaryDataBuffer(item.index ?? 0, key);
    attachments.push({
      filename: meta.fileName || key,
      content_b64: buffer.toString('base64'),
    });
  }

  out.push({
    json: {
      sender: headers.from || item.json.from || '',
      subject: headers.subject || item.json.subject || '(sans objet)',
      body: item.json.text || item.json.snippet || '',
      thread_id: `n8n-${item.json.id}`,
      // L'API borne à 10 pièces jointes / 20 Mo décodés et refuse en 422 avant tout appel LLM.
      attachments: attachments.slice(0, 10),
    },
  });
}

return out;

// Met en forme l'alerte destinée à l'équipe commerciale.
//
// Les drapeaux de risque contractuel (§13) et d'injection de prompt (§15.1.4) sont remontés en
// tête : c'est exactement l'information qui doit changer la façon dont un humain relit le
// brouillon avant de valider.

const data = $json.body.data || {};
const info = data.extracted_info || {};
const alerts = [];

if ((data.risk_flags || []).length) {
  alerts.push(`:warning: Risques contractuels : ${data.risk_flags.join(', ')}`);
}
if ((data.injection_flags || []).length) {
  alerts.push(`:shield: Tentative d'injection de prompt détectée — relire avec méfiance.`);
}
if (data.knowledge_gap) {
  alerts.push(`:grey_question: Question sans réponse en base de connaissances.`);
}

return [{
  json: {
    thread_id: data.thread_id,
    classification: data.classification,
    entreprise: info.entreprise || 'entreprise inconnue',
    urgence: info.urgence || '?',
    sender: data.sender,
    alerts: alerts.join('\n'),
    resume: `${data.classification} — ${info.entreprise || 'entreprise inconnue'} (${data.sender})`,
  },
}];
